const response = $input.first().json;

if (response?.error) {
  throw new Error(
    `Meta API error ${response.error.code ?? ''}: ${response.error.message ?? JSON.stringify(response.error)}`
  );
}

const pages = Array.isArray(response?.data) ? response.data : [];

const normalized = pages.map((page) => ({
  facebook_page_id: page.id,
  facebook_page_name: page.name,
  facebook_tasks: page.tasks ?? [],
  instagram_connected: Boolean(page.instagram_business_account),
  instagram_account_id: page.instagram_business_account?.id ?? null,
  instagram_username: page.instagram_business_account?.username ?? null,
  instagram_name: page.instagram_business_account?.name ?? null,
  instagram_followers: page.instagram_business_account?.followers_count ?? null,
  instagram_media_count: page.instagram_business_account?.media_count ?? null,
  instagram_profile_picture_url:
    page.instagram_business_account?.profile_picture_url ?? null,
}));

const virya = normalized.find(
  (page) =>
    page.facebook_page_id === '101848539107631' ||
    page.instagram_account_id === '17841455886865962' ||
    page.instagram_username === 'virya.official'
);

if (!virya) {
  throw new Error('Nie znaleziono strony Facebook Virya ani konta Instagram virya.official.');
}

return [
  {
    json: {
      success: true,
      primary_account: virya,
      all_accounts: normalized,
      facebook_pages_found: normalized.length,
    },
  },
];
